"""Candidate token verification and signature validation helpers."""

from __future__ import annotations

TOKEN_PREFIX_ALLOWLIST = ("cand1:", "pubbundle1:", "snapmanifest1:")


def validate_token_signature(raw_token: str, *, required_prefix: str) -> bool:
    """Check that raw_token starts with required_prefix and has a non-empty hex suffix."""
    if not raw_token.startswith(required_prefix):
        return False
    digest_part = raw_token[len(required_prefix) :]
    return len(digest_part) >= 8 and all(ch in "0123456789abcdef" for ch in digest_part)


def verify_candidate_token(candidate_token: str, *, expected_prefix: str = "cand1:") -> bool:
    """Verify candidate token prefix allowlist and signature format for rotation audit."""
    if expected_prefix not in TOKEN_PREFIX_ALLOWLIST:
        return False
    return validate_token_signature(candidate_token, required_prefix=expected_prefix)

