"""Deterministic route dispatch table and target normalization."""

from __future__ import annotations


def normalize_dispatch_target(raw_target: str) -> str:
    """Normalize a route target identifier by stripping whitespace and lowercasing scheme."""
    cleaned = raw_target.strip()
    if "://" in cleaned:
        scheme, rest = cleaned.split("://", 1)
        return f"{scheme.lower()}://{rest}"
    return cleaned


class RouteDispatchTable:
    """Maintains deterministic route entries for operator escalation workflows."""

    def __init__(self, routes: dict[str, str] | None = None) -> None:
        self._routes: dict[str, str] = {
            key: normalize_dispatch_target(val) for key, val in (routes or {}).items()
        }

    def lookup(self, route_key: str) -> str:
        """Return normalized route target or raise KeyError when absent."""
        if route_key not in self._routes:
            raise KeyError(f"unknown route_key: {route_key}")
        return self._routes[route_key]


def resolve_route_entry(table: RouteDispatchTable, route_key: str) -> str:
    """Resolve a route key against RouteDispatchTable."""
    return table.lookup(route_key)
